CREATE INDEX idx_orders_user_created ON orders (user_id, created_at);

-- uses the index (left-most column present, sorted walk, stops at 20)
SELECT * FROM orders WHERE user_id = 42 ORDER BY created_at DESC LIMIT 20;

-- CANNOT use it: skips the left-most column
SELECT * FROM orders WHERE created_at > '2026-01-01';

-- index killers
WHERE LOWER(email) = 'a@b.com'   -- function on column
WHERE email LIKE '%gmail.com'    -- leading wildcard
WHERE email = 12345              -- type mismatch → implicit cast

EXPLAIN SELECT ...;  -- type ALL = full scan (bad); ref / range = index used
